   Body.color=Lid.color=Color.white;Lid.rectTransform.localEulerAngles=Vector3.zero;Crank.rectTransform.localEulerAngles=Vector3.zero;Door.rectTransform.localScale=Vector3.one;foreach(var i in icons)i.canvasRenderer.SetAlpha(0);foreach(var l in labels)l.canvasRenderer.SetAlpha(0);
   bool reduced=game.State.Workshop.reducedMotion||!game.State.Settings.effects;running=StartCoroutine(Animate(kind,rewards,reduced));if(reduced)ShortenButton.GetComponentInChildren<Text>().text=UiLocalizedText.Translate("Schließen",game.State.Settings.language);
  }
  IEnumerator Animate(string kind,List<RewardVisual> rewards,bool reduced){float elapsed=0,skipped=0;double began=ReceiptMotion.Now;bool sounded=false;bool cranked=false;float reveal=kind=="purchase"?.1f:kind=="capsule"?1.74f:kind=="drone"?.9f:.88f;float finish=reveal+(kind=="drone"?3.2f:.8f)+Mathf.Min(.4f,rewards.Count*.055f);while(elapsed<finish+.42f){if(route!=game.CurrentTab){Cancel();yield break;}elapsed=ReceiptMotion.Age(began)+skipped;if(reduced)elapsed=Mathf.Max(elapsed,reveal+.55f);if(shorten&&elapsed<finish){skipped+=finish-elapsed;elapsed=finish;}Elapsed=elapsed;float t=elapsed;if(kind=="capsule"&&!cranked){cranked=true;game.Audio?.Play("gumball-turn");}Heading.canvasRenderer.SetAlpha((kind=="drone"?ReceiptMotion.Ease((t-.64f)/.18f):1)*(1-ReceiptMotion.Ease((t-finish)/.42f)));ShortenButton.gameObject.SetActive(t<finish);CloseButton.gameObject.SetActive(t<finish);Shade.color=new Color(.01f,.025f,.045f,(kind=="purchase"?.92f:kind=="chest"?1f:kind=="drone"?.64f:1f)*(1-ReceiptMotion.Ease((t-finish)/.42f)));
