    if(t>=reveal&&!sounded){sounded=true;game.Audio?.Play(kind=="purchase"?"purchase-confirm":kind=="capsule"?"gumball-open":"research-complete");if(!reduced)PixelImpact.Play(Stage,"ReceiptImpact",new Vector2(0,kind=="drone"?-38:30),kind=="purchase"?70:rewards.Exists(r=>r.Item!=null)?100+18*Mathf.Min(4,rewards.Find(r=>r.Item!=null).Item.rarity):100,rewards.Exists(r=>r.Item!=null)?ItemPortrait.RarityColor(rewards.Find(r=>r.Item!=null).Item.rarity):GameTheme.Gold,rewards.Exists(r=>r.Item!=null)?Mathf.Min(.32f,.16f+.04f*rewards.Find(r=>r.Item!=null).Item.rarity):.18f);}
    float retire=ReceiptMotion.Ease((t-reveal)/.24f);if(kind=="chest")Chest.SetOpacity(1-ReceiptMotion.Ease((t-finish)/.42f));else if(kind!="capsule") Body.color=Lid.color=new Color(1,1,1,1-retire);if(kind!="capsule")Crank.color=Door.color=Capsule.color=new Color(1,1,1,1-retire);
    int itemIndex=rewards.FindIndex(r=>r.Item!=null);for(int j=0;j<rewards.Count;j++){var reward=rewards[j];float enter=ReceiptMotion.Out((t-reveal-j*.055f)/.22f);int resources=rewards.Count-(itemIndex>=0?1:0);int index=j-(itemIndex>=0&&j>itemIndex?1:0);float width=Mathf.Min(300,Stage.rect.width-24);int columns=Mathf.Min(5,resources);Vector2 resting=reward.Item!=null?new Vector2(0,65):new Vector2((index%columns-(columns-1)*.5f)*width/columns,(itemIndex>=0?-100:35)-(index/columns)*55);var icon=icons[j];var label=labels[j];icon.sprite=reward.Sprite;icon.rectTransform.anchorMin=icon.rectTransform.anchorMax=Vector2.one*.5f;icon.rectTransform.sizeDelta=Vector2.one*(rewards.Count==1?(kind=="purchase"?64:88):resources>5?32:42);label.rectTransform.anchorMin=label.rectTransform.anchorMax=Vector2.one*.5f;label.rectTransform.sizeDelta=new Vector2(reward.Item!=null||rewards.Count==1?290:width/Mathf.Max(1,columns)-4,reward.Item!=null?42:32);label.text=reward.Label+((rewards.Count==1||kind=="drone")&&reward.Name!=""?(kind=="drone"?"\n":" ")+reward.Name:"");label.color=reward.Item!=null?GameTheme.Text:reward.Tint;label.resizeTextForBestFit=true;label.resizeTextMinSize=11;label.resizeTextMaxSize=rewards.Count==1?18:13;label.fontSize=label.resizeTextMaxSize;Vector2 pos=kind=="purchase"&&Origin.HasValue?ReceiptMotion.Arc(Stage.InverseTransformPoint(Origin.Value),resting,enter,30):resting+Vector2.down*(1-enter)*22;if(kind=="chest"){resting=reward.Item!=null?new Vector2(0,110):new Vector2((index%columns-(columns-1)*.5f)*width/columns,(itemIndex>=0?-38:60)-(index/columns)*50);pos=reduced?resting:ReceiptMotion.Arc(Stage.InverseTransformPoint(Chest.Mouth),resting,enter,38);label.rectTransform.sizeDelta=new Vector2(label.rectTransform.sizeDelta.x,reward.Item!=null?42:22);}if(kind=="capsule"&&!reduced)pos=ReceiptMotion.Arc(new Vector2(0,30),resting,enter,20);if(kind=="drone"){
     bool dense=resources>6;icon.rectTransform.sizeDelta=Vector2.one*(dense?48:58);int cols=Mathf.Min(3,resources);int rows=Mathf.CeilToInt(resources/(float)Mathf.Max(1,cols));resting=reward.Item!=null?new Vector2(0,dense?225:125):new Vector2((index%cols-(cols-1)*.5f)*width/cols,(itemIndex>=0?(dense?65:-31):dense?deliveryHeight/2-110:30+(rows-1)*30)-(index/cols)*(dense?94:110));
     pos=reduced?resting:ReceiptMotion.Arc(new Vector2(0,-38),resting,enter,24);
