    }float transfer=reduced?0:ReceiptMotion.Ease((t-finish)/.42f);if(transfer>0&&reward.Target!=null)pos=ReceiptMotion.Arc(resting,Stage.InverseTransformPoint(reward.Target.position),transfer,32);icon.rectTransform.anchoredPosition=pos;label.rectTransform.anchoredPosition=resting+Vector2.down*(reward.Item!=null?(kind=="chest"?98:104):kind=="drone"?(resources>6?44:53):rewards.Count==1?68:kind=="chest"?28:34);icon.canvasRenderer.SetAlpha(reward.Item!=null?0:enter*(1-transfer*.65f));label.canvasRenderer.SetAlpha(enter*(1-transfer));if(reward.Item!=null&&enter>0){if(!Portrait.gameObject.activeSelf){Portrait.ShowLevel=false;Portrait.Bind(reward.Item);Portrait.gameObject.SetActive(true);}var pr=(RectTransform)Portrait.transform;pr.anchoredPosition=pos;pr.sizeDelta=Vector2.one*Mathf.Lerp(kind=="chest"?148:164,42,transfer);pr.localScale=Vector3.one*(.8f+.2f*enter)*ReceiptMotion.Settle(enter);Portrait.Frame.Reveal=enter;Portrait.Frame.SetVerticesDirty();Portrait.Art.canvasRenderer.SetAlpha(enter);}}
